//! Export stubs of the version.dll proxy (generated by build.rs).

use windows_sys::Win32::System::LibraryLoader::{GetProcAddress, LoadLibraryW};
use windows_sys::Win32::System::SystemInformation::GetSystemDirectoryW;

include!(concat!(env!("OUT_DIR"), "/exports.rs"));

/// Real function addresses, in the order of `NAMES`; read by the stubs.
#[no_mangle]
static mut DW_REAL_VERSION: [usize; NAMES.len()] = [0; NAMES.len()];

core::arch::global_asm!(include_str!(concat!(env!("OUT_DIR"), "/proxy.s")), real = sym DW_REAL_VERSION);

/// Loads System32\version.dll and fills the jump table. Must run in DllMain,
/// before the game can call any export. Returns false when the real DLL is missing.
pub fn init() -> bool {
    let mut dir = [0u16; 260];
    // SAFETY: valid buffer; the call writes at most its length.
    let n = unsafe { GetSystemDirectoryW(dir.as_mut_ptr(), dir.len() as u32) } as usize;
    if n == 0 || n > dir.len() - 16 {
        return false;
    }
    let mut path: Vec<u16> = dir[..n].to_vec();
    path.extend("\\version.dll\0".encode_utf16());
    // SAFETY: NUL-terminated path. version.dll only depends on modules that are
    // already loaded, which keeps this safe enough under the loader lock.
    let real = unsafe { LoadLibraryW(path.as_ptr()) };
    if real.is_null() {
        return false;
    }
    for (i, name) in NAMES.iter().enumerate() {
        // SAFETY: NUL-terminated ASCII name; the table is only written here,
        // before any stub can run.
        unsafe {
            DW_REAL_VERSION[i] = GetProcAddress(real, name.as_ptr()).map(|f| f as usize).unwrap_or(0);
        }
    }
    true
}
